package be.kdg.parkwise.service.impl;

import be.kdg.parkwise.service.AnalyticsService;
import org.springframework.context.annotation.Primary;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;

import java.util.HashMap;
import java.util.Map;

/**
 * Analytics Service that fetches pre-generated charts from the database.
 * Charts are generated by the Python script and stored in analytics_cache table.
 */
@Service
@Primary
public class AnalyticsServiceDbImpl implements AnalyticsService {

    private final JdbcTemplate jdbcTemplate;

    public AnalyticsServiceDbImpl(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    /**
     * Fetch a chart from the analytics_cache table
     */
    private Map<String, Object> getChartFromDb(String chartName) {
        try {
            String sql = """
                SELECT chart_image, chart_data, metadata, generated_at
                FROM analytics_cache
                WHERE chart_name = ?
                """;

            return jdbcTemplate.queryForObject(sql, (rs, rowNum) -> {
                Map<String, Object> result = new HashMap<>();
                result.put("image", rs.getString("chart_image"));
                result.put("data", rs.getString("chart_data"));
                result.put("metadata", rs.getString("metadata"));
                result.put("generated_at", rs.getTimestamp("generated_at"));
                return result;
            }, chartName);

        } catch (Exception e) {
            return createErrorResponse("Chart not found: " + chartName + ". Run the Python chart generator first.");
        }
    }

    @Override
    public Map<String, Object> getOccupancyOverTime() {
        return getChartFromDb("occupancy_time_series");
    }

    @Override
    public Map<String, Object> getSpotHeatmap() {
        return getChartFromDb("heatmap_hour_day");
    }

    @Override
    public Map<String, Object> getDistanceScatter() {
        return getChartFromDb("weather_impact_scatter");
    }

    @Override
    public Map<String, Object> getPeakHours() {
        // This endpoint can still query live data
        try {
            String sql = """
                SELECT
                    EXTRACT(HOUR FROM sr.reading_time) as hour,
                    COUNT(*) FILTER (WHERE sr.occupied = true) as occupied_count,
                    COUNT(*) as total_readings,
                    ROUND(100.0 * COUNT(*) FILTER (WHERE sr.occupied = true) / COUNT(*), 2) as occupancy_rate
                FROM sensor_readings sr
                WHERE sr.reading_time >= NOW() - INTERVAL '7 days'
                GROUP BY hour
                ORDER BY occupancy_rate DESC
                LIMIT 5
                """;

            var peakHours = jdbcTemplate.queryForList(sql);
            Map<String, Object> result = new HashMap<>();
            result.put("peak_hours", peakHours);
            return result;

        } catch (Exception e) {
            return createErrorResponse("Failed to fetch peak hours: " + e.getMessage());
        }
    }

    @Override
    public Map<String, Object> getStats() {
        try {
            Map<String, Object> stats = new HashMap<>();

            // Total readings last 24h
            Integer totalReadings = jdbcTemplate.queryForObject(
                    "SELECT COUNT(*) FROM sensor_readings WHERE reading_time >= NOW() - INTERVAL '24 hours'",
                    Integer.class
            );
            stats.put("total_readings_24h", totalReadings);

            // Occupied spots now
            Integer occupiedSpots = jdbcTemplate.queryForObject(
                    """
                    SELECT COUNT(DISTINCT s.spot_id)
                    FROM sensors s
                    JOIN sensor_readings sr ON s.sensor_id = sr.sensor_id
                    WHERE sr.reading_time >= NOW() - INTERVAL '5 minutes'
                    AND sr.occupied = true
                    """,
                    Integer.class
            );
            stats.put("occupied_spots", occupiedSpots);

            // Total spots
            Integer totalSpots = jdbcTemplate.queryForObject(
                    "SELECT COUNT(*) FROM parking_spots",
                    Integer.class
            );
            stats.put("total_spots", totalSpots);
            stats.put("available_spots", totalSpots - occupiedSpots);

            // Average occupancy last 24h
            Double avgOccupancy = jdbcTemplate.queryForObject(
                    """
                    SELECT ROUND(100.0 * COUNT(*) FILTER (WHERE occupied = true) / COUNT(*), 2)
                    FROM sensor_readings
                    WHERE reading_time >= NOW() - INTERVAL '24 hours'
                    """,
                    Double.class
            );
            stats.put("avg_occupancy_24h", avgOccupancy != null ? avgOccupancy : 0.0);

            return stats;

        } catch (Exception e) {
            return createErrorResponse("Failed to fetch stats: " + e.getMessage());
        }
    }

    @Override
    public Map<String, Object> getAIPredictions() {
        // Keep AI predictions from the existing API or implement database-based approach
        return createErrorResponse("AI predictions not implemented in database version");
    }

    @Override
    public Map<String, Object> getAIForecast() {
        return createErrorResponse("AI forecast not implemented in database version");
    }

    @Override
    public Map<String, Object> getAIBusynessChart() {
        return getChartFromDb("busyness_distribution");
    }

    private Map<String, Object> createErrorResponse(String message) {
        Map<String, Object> error = new HashMap<>();
        error.put("error", message);
        error.put("image", null);
        return error;
    }
}